"""Safe-config span attributes for ASR spans (never secrets/URLs)."""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, Dict

from rasa.tracing.voice.shared import semconv

if TYPE_CHECKING:
    from rasa.core.channels.voice_stream.asr.asr_engine import ASREngine


def engine_attributes(engine: "ASREngine") -> Dict[str, Any]:
    """Safe-config attributes for an ASR span."""
    attributes: Dict[str, Any] = {semconv.VOICE_ASR_PROVIDER: engine.name()}
    language_config = engine.current_language_config
    if language_config.rasa_language_key:
        attributes[semconv.VOICE_LOCALE] = language_config.rasa_language_key
    if language_config.engine_language_key:
        attributes[semconv.VOICE_ASR_LANGUAGE] = language_config.engine_language_key
    if language_config.model:
        attributes[semconv.VOICE_ASR_MODEL] = language_config.model
    return attributes


def connect_attributes(engine: "ASREngine", reconnect: bool) -> Dict[str, Any]:
    """Safe-config attributes for a `connect asr` span."""
    attributes = engine_attributes(engine)
    if reconnect:
        attributes[semconv.VOICE_CONNECT_RECONNECT] = True
    return attributes
